package com.macro.mall.operations.dao;

import java.util.*;
import org.apache.ibatis.annotations.*;

public interface HandoffSemanticDao {
 String F="p.case_ref AS caseRef,p.version,p.projection_json AS projection,p.projection_hash AS projectionHash,p.quality,p.index_state AS indexState,p.embedding_version AS embeddingVersion,p.template_version AS templateVersion,r.business_topic AS topic,r.trigger_source AS source,r.customer_reason AS customerReason,r.stage,r.confirmed_at AS createdAt";
 String LIVE=" FROM ai_handoff_problem p JOIN ai_handoff_record r ON r.case_ref=p.case_ref WHERE p.deleted_at IS NULL AND r.projection_cleared=0";
 @Select("SELECT "+F+LIVE+" AND p.case_ref=#{ref}") Map<String,Object> problem(@Param("ref") String ref);
 @Select("<script>SELECT "+F+LIVE+" AND r.confirmed_at >= DATE_SUB(UTC_TIMESTAMP(),INTERVAL #{days} DAY)<if test='topic != null'> AND r.business_topic=#{topic}</if> ORDER BY p.case_ref LIMIT 5001</script>") List<Map<String,Object>> candidates(@Param("days") int days,@Param("topic") String topic);
 @Select("SELECT COUNT(*) AS total,SUM(p.quality='READY') AS contentReady,SUM(p.index_state='READY') AS indexed,SUM(m.case_ref IS NOT NULL) AS grouped FROM ai_handoff_record r LEFT JOIN ai_handoff_problem p ON p.case_ref=r.case_ref AND p.deleted_at IS NULL LEFT JOIN ai_handoff_problem_member m ON m.case_ref=r.case_ref AND m.taxonomy='issues-v1' WHERE r.projection_cleared=0 AND r.confirmed_at >= DATE_SUB(UTC_TIMESTAMP(),INTERVAL #{days} DAY)") Map<String,Object> coverage(@Param("days") int days);
 @Select("SELECT "+F+",p.deleted_at AS deletedAt"+" FROM ai_handoff_problem p JOIN ai_handoff_record r ON r.case_ref=p.case_ref WHERE p.attempts<3 AND (p.index_state IN ('PENDING','RETRYABLE','DELETE_PENDING') OR (p.index_state='RUNNING' AND p.lease_until<UTC_TIMESTAMP())) ORDER BY p.created_at,p.case_ref LIMIT 1 FOR UPDATE") Map<String,Object> next();
 @Update("UPDATE ai_handoff_problem SET index_state='FAILED',lease_ref=NULL WHERE index_state='RUNNING' AND lease_until<UTC_TIMESTAMP() AND attempts>=3") int exhausted();
 @Update("UPDATE ai_handoff_problem SET index_state='RUNNING',attempts=attempts+1,lease_ref=#{lease},lease_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 60 SECOND) WHERE case_ref=#{ref}") int lease(@Param("ref") String ref,@Param("lease") String lease);
 @Update("UPDATE ai_handoff_problem SET index_state=#{state},embedding_version=#{model},lease_ref=NULL,lease_until=NULL WHERE case_ref=#{ref} AND lease_ref=#{lease} AND lease_until>UTC_TIMESTAMP() AND projection_hash=#{hash} AND version=#{version} AND ((deleted_at IS NULL AND #{state} IN ('READY','RETRYABLE','FAILED')) OR (deleted_at IS NOT NULL AND #{state} IN ('DELETED','RETRYABLE')))") int finish(Map<String,Object> q);
 @Update("UPDATE ai_handoff_problem SET projection_json='{}',deleted_at=UTC_TIMESTAMP(),version=version+1,index_state='DELETE_PENDING',attempts=0,lease_ref=NULL WHERE case_ref=#{ref} AND deleted_at IS NULL") int tombstone(@Param("ref") String ref);
 @Insert("INSERT INTO ai_handoff_problem_group(group_ref,title,topic,actor_ref,created_at,updated_at) VALUES(#{ref},#{title},#{topic},#{actor},UTC_TIMESTAMP(),UTC_TIMESTAMP())") int create(Map<String,Object> q);
 @Select("SELECT group_ref AS groupRef,title,topic,version,created_at AS createdAt FROM ai_handoff_problem_group ORDER BY updated_at DESC LIMIT 100") List<Map<String,Object>> groups();
 @Select("SELECT group_ref AS groupRef,title,topic,version FROM ai_handoff_problem_group WHERE group_ref=#{ref} FOR UPDATE") Map<String,Object> group(@Param("ref") String ref);
 @Update("UPDATE ai_handoff_problem_group SET version=version+1,updated_at=UTC_TIMESTAMP() WHERE group_ref=#{ref} AND version=#{version}") int advance(@Param("ref") String ref,@Param("version") int version);
 @Select("SELECT case_ref AS caseRef,projection_version AS projectionVersion,basis FROM ai_handoff_problem_member WHERE group_ref=#{ref} ORDER BY case_ref") List<Map<String,Object>> members(@Param("ref") String ref);
 @Insert("INSERT INTO ai_handoff_problem_member(case_ref,group_ref,projection_version,basis,actor_ref,created_at) VALUES(#{caseRef},#{ref},#{projectionVersion},#{basis},#{actor},UTC_TIMESTAMP())") int add(Map<String,Object> q);
 @Delete("DELETE FROM ai_handoff_problem_member WHERE group_ref=#{ref} AND case_ref=#{caseRef}") int remove(Map<String,Object> q);
 @Select("SELECT payload_hash AS payloadHash,group_ref AS groupRef,actor_ref AS actor FROM ai_handoff_semantic_audit WHERE request_ref=#{requestRef}") Map<String,Object> request(@Param("requestRef") String ref);
 @Insert("INSERT INTO ai_handoff_semantic_audit(request_ref,payload_hash,group_ref,case_ref,action,actor_ref,created_at) VALUES(#{requestRef},#{payloadHash},#{ref},#{caseRef},#{action},#{actor},UTC_TIMESTAMP())") int audit(Map<String,Object> q);
 @Update("UPDATE ai_handoff_group_analysis SET state='STALE',lease_ref=NULL WHERE group_ref=#{ref} AND state<>'CLEARED'") int invalidate(@Param("ref") String ref);
 @Update("UPDATE ai_handoff_group_analysis a JOIN ai_handoff_analysis_source s ON s.analysis_ref=a.analysis_ref SET a.state='CLEARED',a.snapshot_json=NULL,a.result_json=NULL,a.lease_ref=NULL WHERE s.case_ref=#{ref}") int clearAnalysis(@Param("ref") String ref);
 @Insert("INSERT INTO ai_handoff_analysis_source(analysis_ref,case_ref) VALUES(#{analysisRef},#{caseRef})") int analysisSource(@Param("analysisRef") String analysisRef,@Param("caseRef") String caseRef);
 @Select("SELECT action,case_ref AS caseRef,created_at AS createdAt FROM ai_handoff_semantic_audit WHERE group_ref=#{ref} ORDER BY created_at,request_ref") List<Map<String,Object>> history(@Param("ref") String ref);
 @Update("UPDATE ai_handoff_problem SET index_state='PENDING',attempts=0,lease_ref=NULL,lease_until=NULL WHERE deleted_at IS NULL AND quality='READY'") int rebuild();
 @Insert("INSERT INTO ai_handoff_group_analysis(analysis_ref,group_ref,group_version,snapshot_json,snapshot_hash,state,actor_ref,created_at) VALUES(#{analysisRef},#{ref},#{version},#{snapshot},#{snapshotHash},'PENDING',#{actor},UTC_TIMESTAMP())") int analysis(Map<String,Object> q);
 @Select("SELECT analysis_ref AS analysisRef,group_ref AS groupRef,group_version AS groupVersion,state,result_json AS result,model_version AS modelVersion,snapshot_hash AS snapshotHash FROM ai_handoff_group_analysis WHERE group_ref=#{ref} ORDER BY created_at DESC LIMIT 20") List<Map<String,Object>> analyses(@Param("ref") String ref);
 @Select("SELECT analysis_ref AS analysisRef,group_ref AS groupRef,group_version AS groupVersion,snapshot_json AS snapshot,snapshot_hash AS snapshotHash FROM ai_handoff_group_analysis WHERE attempts<2 AND (state='PENDING' OR (state='RUNNING' AND lease_until<UTC_TIMESTAMP())) ORDER BY created_at LIMIT 1 FOR UPDATE") Map<String,Object> nextAnalysis();
 @Update("UPDATE ai_handoff_group_analysis SET state='RUNNING',attempts=attempts+1,lease_ref=#{lease},lease_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 90 SECOND) WHERE analysis_ref=#{ref}") int analysisLease(@Param("ref") String ref,@Param("lease") String lease);
 @Update("UPDATE ai_handoff_group_analysis a JOIN ai_handoff_problem_group g ON g.group_ref=a.group_ref SET a.state=#{state},a.result_json=#{result},a.model_version=#{model},a.lease_ref=NULL WHERE a.analysis_ref=#{analysisRef} AND a.lease_ref=#{lease} AND a.lease_until>UTC_TIMESTAMP() AND a.state='RUNNING' AND a.group_version=g.version AND a.snapshot_hash=#{snapshotHash}") int analysisFinish(Map<String,Object> q);
 @Select("SELECT snapshot_json AS snapshot,state,group_ref AS groupRef,group_version AS groupVersion FROM ai_handoff_group_analysis WHERE analysis_ref=#{ref} FOR UPDATE") Map<String,Object> analysisByRef(@Param("ref") String ref);
 @Update("UPDATE ai_handoff_group_analysis SET state='REVIEWED',reviewed_by=#{actor} WHERE analysis_ref=#{ref} AND state='DRAFT'") int reviewAnalysis(@Param("ref") String ref,@Param("actor") String actor);
 @Insert("INSERT INTO ai_handoff_improvement_evidence(improvement_ref,group_ref,group_version,analysis_ref,verification_method,evidence_ref,actor_ref,created_at) VALUES(#{improvementRef},#{ref},#{version},#{analysisRef},#{method},#{evidence},#{actor},UTC_TIMESTAMP())") int evidence(Map<String,Object> q);
 @Select("SELECT group_ref AS groupRef,group_version AS groupVersion,analysis_ref AS analysisRef,verification_method AS verificationMethod,evidence_ref AS evidenceRef FROM ai_handoff_improvement_evidence WHERE improvement_ref=#{ref}") Map<String,Object> evidenceFor(@Param("ref") String ref);
 @Select("SELECT COUNT(*) FROM ai_operations_improvement i JOIN ai_handoff_problem_member m ON m.case_ref=i.case_ref WHERE i.improvement_ref=#{ref}") int groupedImprovement(@Param("ref") String ref);
 @Select("SELECT COUNT(*) FROM ai_operations_improvement i JOIN ai_handoff_problem_member m ON m.case_ref=i.case_ref WHERE i.improvement_ref=#{improvementRef} AND m.group_ref=#{ref}") int improvementBelongs(Map<String,Object> q);
}
